code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The dominant color is the background; rectangular colored frames get a
    # solid color-2 interior.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    for color in counts:
        if color == bg:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        # Only fill a complete rectangular outline of this color.
        if (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1+1)) and
            all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1+1))):
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
'''
